function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const latest_commit = multisetDiff(before.latest_commit, after.latest_commit);
  const repo = multisetDiff(before.repo, after.repo);
  const repo_latest = multisetDiff(before.repo_latest, after.repo_latest);
  return {
    rels: [
      { rel: "latest_commit", add: latest_commit.add, del: latest_commit.del },
      { rel: "repo", add: repo.add, del: repo.del },
      { rel: "repo_latest", add: repo_latest.add, del: repo_latest.del },
    ],
    carryPending: false,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // coalesce_defaults_the_absent_row: no edge rules -- absorb arrivals, recompute levels, diff.
}

